import{_ as s,o as e,c as i,a0 as t}from"./chunks/framework.DCluYYrN.js";const k=JSON.parse('{"title":"Веб-интерфейс модуля","description":"","frontmatter":{},"headers":[],"relativePath":"ru_RU/guide/module-webui.md","filePath":"ru_RU/guide/module-webui.md"}'),n={name:"ru_RU/guide/module-webui.md"};function p(l,a,r,o,h,c){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="веб-интерфеис-модуля" tabindex="-1">Веб-интерфейс модуля <a class="header-anchor" href="#веб-интерфеис-модуля" aria-label="Permalink to &quot;Веб-интерфейс модуля&quot;">​</a></h1><p>Помимо выполнения загрузочных скриптов и правки системных файлов, модули KernelSU могут показывать пользовательский интерфейс и напрямую взаимодействовать с пользователем.</p><p>Модуль может описать страницу на HTML + CSS + JavaScript, используя любые веб‑технологии. Менеджер KernelSU отображает такие страницы через WebView и предоставляет API для взаимодействия с системой, например для запуска shell-команд.</p><h2 id="каталог-webroot" tabindex="-1">Каталог <code>webroot</code> <a class="header-anchor" href="#каталог-webroot" aria-label="Permalink to &quot;Каталог \`webroot\`&quot;">​</a></h2><p>Файлы веб-ресурсов должны располагаться в подкаталоге <code>webroot</code> в корне модуля, и там <strong>ОБЯЗАТЕЛЬНО</strong> должен находиться файл <code>index.html</code>, выступающий точкой входа. Самая простая структура модуля с веб-интерфейсом выглядит так:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>❯ tree .</span></span>
<span class="line"><span>.</span></span>
<span class="line"><span>|-- module.prop</span></span>
<span class="line"><span>\`-- webroot</span></span>
<span class="line"><span>    \`-- index.html</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>При установке модуля KernelSU автоматически задаёт права доступа и SELinux-контекст для этого каталога. Если вы не уверены, что делаете, не меняйте разрешения вручную!</p></div><p>Если страница содержит CSS или JavaScript, их тоже нужно положить в этот каталог.</p><h2 id="javascript-api" tabindex="-1">JavaScript API <a class="header-anchor" href="#javascript-api" aria-label="Permalink to &quot;JavaScript API&quot;">​</a></h2><p>Если это только страница отображения, она работает как обычный веб-сайт. Но самое главное — KernelSU предоставляет набор системных API, позволяющих реализовать модуль‑специфичные функции.</p><p>KernelSU предлагает JavaScript-библиотеку, опубликованную в <a href="https://www.npmjs.com/package/kernelsu" target="_blank" rel="noreferrer">npm</a>, которую можно использовать в коде страницы.</p><p>Например, можно выполнить shell-команду, чтобы получить конфигурацию или изменить свойство:</p><div class="language-JavaScript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">JavaScript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { exec } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;kernelsu&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">errno</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">stdout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> exec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;getprop ro.product.model&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Также можно переключить страницу в полноэкранный режим или показать toast.</p><p><a href="https://www.npmjs.com/package/kernelsu" target="_blank" rel="noreferrer">Документация по API</a></p><p>Если существующего API недостаточно или им неудобно пользоваться, оставьте нам предложение <a href="https://github.com/tiann/KernelSU/issues" target="_blank" rel="noreferrer">здесь</a>!</p><h2 id="несколько-советов" tabindex="-1">Несколько советов <a class="header-anchor" href="#несколько-советов" aria-label="Permalink to &quot;Несколько советов&quot;">​</a></h2><ol><li><code>localStorage</code> можно использовать как обычно для хранения данных, но помните, что всё будет удалено при удалении приложения‑менеджера. Для постоянного хранения сохраните данные вручную в отдельном каталоге.</li><li>Для простых страниц мы рекомендуем использовать <a href="https://parceljs.org/" target="_blank" rel="noreferrer">parceljs</a> для сборки. Он не требует начальной настройки и очень прост. Но если вы опытный фронтенд‑разработчик или у вас есть собственные предпочтения, смело используйте любой другой инструмент!</li></ol>`,18)])])}const u=s(n,[["render",p]]);export{k as __pageData,u as default};
